fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    // The two input arrays must have the same length.
    assert_eq!(arr1.len(), arr2.len(), "Input arrays must have the same length");

    // Perform element-wise integer division.
    // We assume arr2 contains no zeros and that each quotient fits in i32,
    // but since we're returning u32, we only rely on the problem's guarantees.
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&numer, &denom)| {
            // denom != 0 is guaranteed by the problem statement
            numer / denom
        })
        .collect()
}

